class DispatchJobService{static $inject=["$mdDialog","$document","DispatchData","moment"];constructor($mdDialog,$document,DispatchData,moment){this._$mdDialog=$mdDialog;this._$document=$document;this._dispatchData=DispatchData;this._moment=moment;this._pickCouriers=[];this._pickAllCouriers=[];this._fetchCouriersData()}_fetchCouriersData(){this._fetchActiveCouriersData();this._fetchAllCouriersData()}_fetchActiveCouriersData(){this._dispatchData.getActiveCouriers().then(data=>this._pickCouriers=data)}_fetchAllCouriersData(){this._dispatchData.getAllCouriers().then(data=>this._pickAllCouriers=data)}async dispatchJobByJobId(courierNumber,jobId){const job=this._dispatchData.getJobDetail(jobId);const selectedCourier=this._pickAllCouriers.find(c=>c.courierID===courierNumber);await this.dispatchJob(selectedCourier.id,job)}async dispatchJobs(courierNumber,jobs){let foundCourier=await this._findCourier(courierNumber);await this._dispatchJobsContinue(courierNumber,foundCourier,jobs)}async dispatchJob(courierNumber,job){const foundCourier=await this._findCourier(courierNumber);const jobsArray=[job];await this._dispatchJobsContinue(courierNumber,foundCourier,jobsArray)}async _findCourier(courierNumber){this._fetchActiveCouriersData();let foundCourier=this._pickCouriers.find(c=>c.id===courierNumber);if(foundCourier===undefined){const confirm=this._generateOfflineCourierDialog();try{await this._$mdDialog.show(confirm);foundCourier=this._pickAllCouriers.find(c=>c.id===courierNumber)}catch(error){console.log("User chose not to dispatch job as courier is offline")}}return foundCourier}_generateOfflineCourierDialog(){return this._$mdDialog.confirm().title("Courier Offline").textContent("Dispatch anyway?").ok("Yes").cancel("No")}async _dispatchJobsContinue(courierNumber,foundCourier,jobs){let jobIds=[];for(let i=0;i<jobs.length;i++){const job=jobs[i];const jobNumber=job.jobNo;if(job.courierData&&job.courierData.courierID!==null){this._showAlertMessage("Restore "+jobNumber+" prior to dispatching to another courier");continue}if(job.dgClass!==null&&job.dgClass>0&&!foundCourier.dangerousGoods){this._showAlertMessage("DG job "+jobNumber+" can not be dispatched to courier "+courierNumber+" - doesn't have DGLicense.");continue}if(job.dgClass!==null&&job.dgClass>0&&(job.DGLicenseExpiry===null||this._moment(foundCourier.dgLicenseExpiry)<this._moment().add(1,"days"))){this._showAlertMessage("Courier "+courierNumber+" doesn't have a DGLicense or license has expired.");continue}jobIds.push(job.id);await this._dispatchData.allocateJobs(foundCourier.courierID,ContactID,jobIds)}}_showAlertMessage(textContent){const alert=this._$mdDialog.alert().parent(angular.element(this._$document.body)).clickOutsideToClose(true).title("Message").textContent(textContent).ariaLabel("Alert").ok("OK");this._$mdDialog.show(alert)}}angular.module("uDispatch").service("dispatchJobService",DispatchJobService);